questions.safe_code:
1  <%
2  String username = request.getParameter("username");
3  String password = request.getParameter("password");
4  if (username==null || password==null || !isAuthenticatedUser(username, password)) {
5    throw new MyException("인증 에러");
6  }
7  // 인증 여부 등 보안결정 값은 클라이언트 쿠키가 아닌 서버 세션에 저장한다
8  HttpSession session = request.getSession();
9  session.setAttribute("user", username);
10 session.setAttribute("authenticated", "1");
11 %>

